//! Actual third native round, exact bounded history and original shared budget.
use super::*;
struct Env{base:IterationEnv,waits:AtomicUsize}
impl Environment for Env{
 fn capture(&self,o:&Owned)->model::Result<Capture>{self.base.capture(o)}fn configuration(&self)->model::Result<crate::pet_config::Configuration>{self.base.configuration()}fn peer_configuration(&self)->model::Result<(crate::pet_config::Configuration,Settings)>{self.base.peer_configuration()}fn target(&self)->model::Result<Arc<crate::spotify::goal::Target>>{panic!("history is not system authority")}
 fn decide(&self,s:Source)->Option<Decision>{self.base.decide(s)}
 fn notify(&self,s:&Status){if s.phase==Phase::WaitingPeers{self.waits.fetch_add(1,Ordering::AcqRel);self.base.child();}else{self.base.notify(s);}}
}
fn exercise(models:u16,repeat:bool){
 for provider in["ollama","lmstudio"]{
  let s=Arc::new(Setup::new());let deadline=crate::assistant_memory::now()+120_000;let g=s.f.goal_named_criteria(provider,"bounded-three-peer-rounds",vec!["Independent actual result proof".into()]);let to=if provider=="ollama"{"ai_lmstudio"}else{"ai_ollama"};let plan=|subgoal:&str|json!({"kind":"plan","description":"One independently admitted branch","steps":[{"description":"One bounded branch","postcondition":"Receipt is not success","operation":{"operationId":"pet.delegate","version":1,"arguments":{"toPetId":to,"subgoal":subgoal,"criteria":[subgoal],"expiresAt":deadline,"allowance":{"modelCalls":1,"toolCalls":1,"outputBytes":16384},"maxDepth":2}}}]});
  let first=plan("First independent finite task");let second=plan(if repeat{"First independent finite task"}else{"Derived independent finite task"});let third=models==5&&!repeat;let last=json!({"kind":"blocked","reason":"Two actual child outcomes are available but the free parent criterion remains unverified"});let meta=if provider=="lmstudio"{lm_metadata()}else{metadata()};let mut responses=vec![("application/json",meta.to_string()),("text/event-stream",stream(&first.to_string(),true)),("application/json",meta.to_string()),("text/event-stream",stream(&second.to_string(),true))];if third{responses.extend([("application/json",meta.to_string()),("text/event-stream",stream(&last.to_string(),true))]);}let(mut server,http)=crate::pet_runtime::lease_controller::memory_test_http_fixture_idle(responses,|_|{});server.id=provider;
  let(_,o)=parent_with_rounds(&s,&g,&server,deadline,models,6,3);let env=Arc::new(Env{base:IterationEnv{s:s.clone(),provider,url:server.url.clone(),owner:o.clone(),approve_data:true,stop_wait:false,approve_derived:true,busy_delivery:false,delivery_blocked:AtomicBool::new(false),store_lock:Mutex::new(None),child_started:AtomicBool::new(false),decisions:AtomicUsize::new(0),waits:AtomicUsize::new(0),child_requests:Mutex::new(vec![])},waits:AtomicUsize::new(0)});let driver=Driver::new(o.clone(),Arc::new(current_store(&s)),env.clone()).unwrap();let status=run(driver.run()).unwrap_or_else(|e|panic!("{e:?}; {:?}",driver.status()));let requests=http.join().unwrap();assert_eq!(requests.len(),if third{6}else{4});assert_eq!(status.phase,Phase::Limited);assert_eq!(env.base.decisions.load(Ordering::Acquire),if third{4}else{3});assert_eq!(env.waits.load(Ordering::Acquire),2);assert_eq!(o.workers(),0);
  let root=current_store(&s).read(&g.id,&g.spec.owner.pet_id).unwrap();let b=body(&s,&root);assert!(root.completion.is_none());assert_eq!(b["schemaVersion"],43);assert_eq!(b["planningUsage"]["schemaVersion"],5);let rounds=b["planningUsage"]["rounds"].as_array().unwrap();assert_eq!(rounds.len(),if third{3}else{2});assert_eq!(rounds[1]["peerSources"]["history"].as_array().unwrap().len(),1);if third{assert_eq!(rounds[2]["peerSources"]["history"].as_array().unwrap().len(),2);assert_ne!(rounds[1]["peerData"]["id"],rounds[2]["peerData"]["id"]);assert_eq!(rounds[2]["peerData"]["inputHash"],rounds[2]["inputHash"]);}else{assert!(rounds[1]["peerFeedback"].is_object());}assert_eq!(b["delegationReservations"].as_array().unwrap().len(),2);let v=s.a.delegation_view(&root,&root.admissions[0].spec.decision_id,crate::assistant_memory::now()).unwrap();assert_eq!(v.held.unwrap().model_calls,2);assert_eq!(v.remaining.unwrap().model_calls,if repeat{1}else{0});if !third{continue;}
  let messages=requests[5].1["messages"].as_array().unwrap();assert_eq!(messages.len(),5);assert_eq!(messages[1]["content"],first.to_string());assert_eq!(messages[2]["content"],second.to_string());assert!(!messages.iter().any(|m|m.to_string().contains("Private child outcome")));let grant:crate::pet_runtime::authority::Grant=serde_json::from_value(b.clone()).unwrap();assert!(grant.valid());let mut down=grant;down.schema_version=42;assert!(!down.valid());
 }
}

#[test]fn three_native_rounds_review_each_exact_canonical_history_prefix_and_share_one_budget_on_both_engines(){exercise(5,false);}
#[test]fn exhaustion_after_two_actual_branches_finishes_without_an_extra_model_or_data_decision(){exercise(4,false);}
#[test]fn repeated_semantic_child_outcomes_stop_before_another_data_decision_despite_spare_budget(){exercise(5,true);}
